<script setup lang="ts">
import type { Programme } from '../../../../packages/contracts/src/programme';
import {useProgrammeAudio,audioTime} from '../composables/useProgrammeAudio';
const props=defineProps<{programme:Programme}>();
const player=useProgrammeAudio();const {playing,waiting,position,volume,error}=player;
const loaded=computed(()=>player.programme.value?.programmeId===props.programme.programmeId);
const seconds=computed(()=>props.programme.durationMs/1000);const preview=ref<number|null>(null);
const shownPosition=computed(()=>preview.value??(loaded.value?position.value:0));
const chapterIndex=computed(()=>Math.max(0,props.programme.chapters.findIndex(c=>shownPosition.value*1000>=c.startMs&&shownPosition.value*1000<c.endMs)));
const chapterPreview=ref<number|null>(null); const selectedChapter=computed(()=>chapterPreview.value??chapterIndex.value); const chapter=computed(()=>props.programme.chapters[selectedChapter.value]); watch(()=>props.programme.renditionKey,()=>{chapterPreview.value=null;preview.value=null;});
const status=computed(()=>error.value&&loaded.value?'Recording unavailable':waiting.value&&loaded.value?'Buffering':playing.value&&loaded.value?'Playing':loaded.value?'Paused':'Ready to play');
function ensureLoaded(){if(!loaded.value)player.setProgramme(props.programme);}
function toggle(){ensureLoaded();if(playing.value)player.pause();else void player.play();}
function seekPreview(event:Event){preview.value=Number((event.target as HTMLInputElement).value);}
function seekCommit(event:Event){ensureLoaded();player.seek(Number((event.target as HTMLInputElement).value));preview.value=null;}
function chapterTune(index:number){ensureLoaded();const c=props.programme.chapters[index];if(c)player.seek(c.startMs/1000);chapterPreview.value=null;}
function relative(delta:number){ensureLoaded();player.seek(position.value+delta);}
function chapterStep(delta:number){ensureLoaded();player.nextChapter(delta);}
</script>
<template>
  <section class="receiver-object" aria-label="Tabletop Radio">
    <div class="cabinet"><div class="front-panel">
      <header class="maker-plate"><span>THE AGGREGATOR</span><span>READER’S RADIO <b>01</b></span></header>
      <div class="speaker-well" aria-hidden="true"><div class="speaker-mesh"></div><span class="speaker-wordmark">a.</span><span class="speaker-caption">THE LISTENING EDITION</span></div>
      <div class="instrument-panel">
        <div class="glass-bezel"><div class="glass-display">
          <div class="display-status"><span><i :class="{'is-on':loaded&&playing&&!waiting}"></i>{{ status }}</span><span>{{ programme.variant==='brief'?'BRIEF':'FULL EDITION' }}</span></div>
          <h2>{{ programme.title }}</h2>
          <p class="story-title">{{ chapterPreview!==null?'Preview · ':'' }}{{ chapter?.title || 'Prepared local recording' }}</p>
          <div class="display-bottom"><span class="digital-time">{{ audioTime(shownPosition) }}<small> / {{ audioTime(seconds) }}</small></span><span class="remaining">−{{ audioTime(seconds-shownPosition) }}</span></div>
          <RadioMeter :programme-id="programme.programmeId" :rendition-key="programme.renditionKey" />
        </div></div>
        <label class="position-scale"><span class="scale-copy">PROGRAMME POSITION <output>{{ preview===null?'':audioTime(preview)+' · release to seek' }}</output></span><input aria-label="Programme position" type="range" min="0" :max="seconds" step=".1" :value="shownPosition" @input="seekPreview" @change="seekCommit" @pointercancel="preview=null"/><span class="scale-numbers" aria-hidden="true"><span>0</span><span>¼</span><span>½</span><span>¾</span><span>END</span></span></label>
      </div>
      <div class="control-rail">
        <RadioDial class="volume-control" label="Volume" :model-value="volume" :max="1" :step=".05" :value-text="`${Math.round(volume*100)}%`" :disabled="player.volumeUnavailable.value" @input="player.setVolume" />
        <div class="key-bank"><span class="rail-label">TRANSPORT</span><div class="transport-keys"><button type="button" class="transport-key" aria-label="Previous story" @click="chapterStep(-1)"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 5v14M18 5 8 12l10 7Z"/></svg><span>PREV</span></button><button type="button" class="transport-key play-key" :class="{'is-depressed':loaded&&playing}" :aria-label="loaded&&playing?'Pause':'Play'"  @click="toggle"><svg v-if="loaded&&playing" viewBox="0 0 24 24" aria-hidden="true"><path d="M7 5h3v14H7zM14 5h3v14h-3z"/></svg><svg v-else viewBox="0 0 24 24" aria-hidden="true"><path d="m8 4 12 8-12 8Z"/></svg><span>{{ loaded&&playing?'PAUSE':'PLAY' }}</span></button><button type="button" class="transport-key" aria-label="Next story" @click="chapterStep(1)"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M19 5v14M6 5l10 7-10 7Z"/></svg><span>NEXT</span></button></div></div>
        <RadioDial class="chapter-control" label="Story" :model-value="chapterIndex" :max="Math.max(0,programme.chapters.length-1)" :step="1" :value-text="programme.chapters.length?`${selectedChapter+1} of ${programme.chapters.length}`:'No stories'" :revision="programme.renditionKey" :disabled="programme.chapters.length<2||!!error" @preview="chapterPreview=$event" @commit="chapterTune" />
      </div>
      <span class="assembly-screw screw-left" aria-hidden="true"></span><span class="assembly-screw screw-right" aria-hidden="true"></span>
    </div><div class="cabinet-base" aria-hidden="true"><span>LOCAL SYNTHETIC NARRATION · FICTIONAL REPORTING</span><span>PREPARED, NEVER LIVE</span></div></div>
    <div class="receiver-secondary"><MediaKey label="Back 15 seconds" icon="rewind" @click="relative(-15)"/><MediaKey label="Forward 15 seconds" icon="forward" @click="relative(15)"/><MediaKey :label="volume===0?'Unmute':'Mute'" :icon="volume===0?'mute':'volume'" @click="player.toggleMute"/></div>
    <p v-if="player.volumeUnavailable.value" role="status">Use your device’s volume controls; this browser does not support changing media volume here.</p><p v-if="error&&loaded" class="programme-error" role="status">{{ error }}</p><p class="hardware-note">Drag either knob clockwise or counterclockwise. Story changes on release; Escape cancels. Arrows step, Home/End reach limits, Page Up/Down step five. Sliders and −/+ are alternatives. Volume stays in this listening session; device volume may take precedence.</p>
  </section>
</template>
